 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The colored template sits along the top edge; each color forms a vertical-then-horizontal path to its other occurrence.
    top = [(0, c, grid[0][c]) for c in range(w) if grid[0][c] != 0]
    for r0, c0, color in top:
        targets = [(r, c) for r in range(h) for c in range(w)
                   if grid[r][c] == color and (r, c) != (r0, c0)]
        if targets:
            # A color endpoint is placed on one of the other edges; connect to it by an L path.
            r, c = targets[0]
            for rr in range(min(r0, r), max(r0, r) + 1):
                out[rr][c0] = color
            for cc in range(min(c0, c), max(c0, c) + 1):
                out[r][cc] = color
        else:
            for rr in range(h):
                out[rr][c0] = color
    return out
